__NUXT_JSONP__("/ar/programs", (function(a){return {data:[{details:{slug:"ar",pageTitle:"البرامج | Mentor Language Institute",pageDescription:a,title:"البرامج",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fmli_course.jpg",programs:{title:a,lists:["ESL برنامج","Vacation ESL برنامج","TOEFL® Test Preparation \u002F TOEFL® and University Preparation برنامج","IELTS برنامج","Conversation Intermediate برنامج","Conversation Advanced برنامج","Business plus TOEIC ‎برنامج"]},subtitle:["إن جميع الدورات لدينا تعقد باللغة الإنجليزية, يبدأ الطلاب معنا بدورة الإنجليزية كلغة ثانية وهي الدورة العامة, ثم بعد يحققوا مستوى لغة أعلى ينتلقون لدراسة مجالات متخصصة مثل توفل, ايلتس.","※ بعض الفئات تتطلب الحد الأدنى من درجة اختبار التنسيب للانضمام."],services_esl:[{title:"برنامج اللغة الإنجليزية العامة (ESL)",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fesl.png",subtitle:"ويركز هذا البرنامج على كيفية التواصل باللغة الإنجليزية. و هو مفيد في تعزيز المهارات الخاصة بك المجالات الأساسية الأربعة (الكتابة والاستماع والتحدث والقراءة.)",description:["هذه هي الدورة الأكثر شعبية في معهد منتور. \u003Cbr \u002F\u003E وهي مقسمة إلى 8 مستويات.\u003Cbr \u002F\u003Eيمكنك تحسين مهاراتك في اللغة الإنجليزية بناء على ماتحتاج تطويره."],youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FAq_MfkF3x0g"}],services_esl_cmar:[{title:"إسل + سمار",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fesl+cmar.png",subtitle:"دروس السمار تقوم على إدارة المحادثة, وتقليل أخطاء اللهجة مما يعني تصحيح النطق",description:["بالإضافة إلى برامج إسل، ويهدف هذا البرنامج إلى تعزيز مهارات النطق.\u003Cbr \u002F\u003E هذا البرنامج يقوم أيضا على تدريب الطلاب على النقط الصحيح للحروف الساكنة و الحروف المتحركة, حيث أن الطالب يستمع بشكل مكثف لتحسين مهارات الإستماع.\u003Cbr \u002F\u003Eالاستماع إلى النطق الصحيح مرارا وتكرارا يؤدي أيضا إلى تحسين مهارات الاستماع."]}],services_toefl:[{title:"TOEFL® Test Preparation \u002F TOEFL® and University Preparation",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Ftoefl.png",link:"https:\u002F\u002Fmliesl.edu\u002Fcontents\u002Far\u002Fجميع-التغييرات-التي-يجب-أن-تعرفها-اختب\u002F",other_image:"\u002Fimages\u002Fcourses\u002Fcourse\u002FBanner_TOEFL_Jan_21.png",subtitle:"توفل إبت هو اختبار لتقييم إجادة اللغة الإنجليزية لغير الناطقين بها. حيث أن درجة التوفل مطلوبة و معتمدة ليس فقط من الجامعات في الولايات المتحدة بل أيضا الوكالات الحكومية والمؤسسات الخاصة، ومنظمات اكتساب التأهيل، والمؤسسات الدراسية.",description:["ويركز برنامج توفل ®MLI على استراتيجيات الاختبار وتحسين جميع المهارات 4 (الكتابة والاستماع والتحدث والقراءة) للحصول على درجة عالية في اختبار على شبكة الإنترنت (إبت)."],youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FKYPYbU-D3M0"}],services_ielts:[{title:"IELTS™  برنامج",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fielts.jpg",subtitle:"إيلتس ™ هو اختبار تم إعداده في المملكة المتحدة وأستراليا لتقييم إجادة اللغة الإنجليزية للطلاب. في الآونة الأخيرة، أصبح أيلتس معتمد في العديد من الجامعات الأمريكية كبديل  عن درجة التوفل ™",description:["ويتكون البرنامج من أربعة أجزاء: الاستماع والتحدث والقراءة والكتابة.\u003Cbr \u002F\u003Eفي هذه الفئة، سوف تتعلم المهارات \u002F استراتيجيات لتحقيق درجات عالية في كل قسم.","يرى بعض الطلاب أن أيلتس أسهل نسبيا من توفل لهذا فوهو برنامج مثالي للطلاب الذين يجدون صعوبة في اختبار  TOEFL®"],youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002Fho7kUVZoOng"}],services_conversation:[{title:"برنامج المحادثة",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fconversation.png",subtitle:"ويركز هذا البرنامج على محادثة الحياة اليومية ويهدف إلى مساعدة الطلاب على التحدث باللغة الإنجليزية بطلاقة.",description:["برنامجنا يركز على تعزيز مهارات المحادثة باللغة الإنجليزية من خلال أنشطة شيقة وتعلم تفاعلي! في فصول المحادثة لدينا، سيستكشف الطلاب مجموعة واسعة من المفردات والعبارات والتعابير التي ستجعل محادثاتك تنبض بالحياة. امارس نطقك في فصل CMAR لدينا. من خلال مناقشات ممتعة وتمارين الأدوار وأنشطة العمل الجماعي، ستكتسب الثقة في التعبير عن نفسك والمشاركة في محادثات ذات مغزى. يقدم مدرسونا ذوو الخبرة بيئة تعلم داعمة، موجهينك في رحلة اكتشاف اللغة."],youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002Fmg04cOOxTQ4"}],services_toeic:[{title:"Business+TOEIC®  برنامج",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fbusiness-toeic.png",subtitle:"في ميدان التجارة الدولية تعنتبر اللغة الإنجليزية هي اللغة العالمية في العالم, و الهدف من هذا البرنامج هو تحسين مهارات المحادثة في مجال الأعمال باللغة الإنجليزية.",description:["يهدف إلى تحسين مهاراتك في اللغة الإنجليزية تحسين شامل مع المحاكاة العملية مثل عروض الطلاب و المكالمات الهاتفية والمفاوضات والاجتماعات، وكذلك من خلال التركيز على المفردات التجارية والاستماع والكتابة ومهارات المناقشة في مجال الأعمال و التجارة."],youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F2htjAgPz984",other_info:{description:["اختبار TOEIC® هو مؤشر على إجادة اللغة الإنجليزية في الأعمال التجارية وتستخدم من قبل مختلف الشركات والمنظمات في جميع أنحاء العالم. بالإضافة إلى دورة الأعمال القياسية، و TOEIC® دورة إعداد الطلاب للنجاح في TOEIC® - ليزتينينغ و امتحان القراءة من خلال إدخال المفردات الأساسية واستكشاف استراتيجيات لتحقيق درجة عالية على المحك.","سوف تحقق فائدة في تحسين مهاراتك في اللغة الإنجليزية، مثل المفردات، والقراءة، والاستماع، والنحوي من خلال تعلم استراتيجيات للعثور على الإجابات الصحيحة، سوف تساعدك على تحقيق درجة عالية."]}}],services_private:[{title:"Private Lessons",image:"\u002Fimages\u002Fcourses\u002Fcourse\u002Fprivate-lessons.png",subtitle:"يتم تخصيص الدروس الخصوصية لتلبية أهدافك في إعدادات فردية أو جماعية صغيرة.",description:["الدروس الخصوصية هي أكثر خياراتنا مرونة في تعلم اللغة. يقوم المدربون المدربون تدريباً عالياً بتطوير دروس مخصصة مصممة لمساعدتك في تحقيق أهدافك الإنجليزية المحددة. يمكنك دراسة أي شيء من مهارات اللغة الإنجليزية العامة ، والمحادثة ، والطلاقة ، وتقليل اللكنة ، واللغة الإنجليزية للأعمال ، و TOEFL ، و TOEIC ، و GRE ، والمزيد. يمكنك جدولة الدروس الخاصة بناءً على مدى توفرك والسرعة المطلوبة. على سبيل المثال ، إذا كنت ترغب في الدراسة بشكل مكثف ، فيمكنك طلب درس خاص كل يوم لمدة 3 ساعات أو إذا كنت تبحث عن وتيرة أكثر استرخاءً ، يمكنك طلب درس خاص مرة واحدة فقط في الأسبوع لمدة ساعة واحدة. يمكنك الحصول على المرونة والتعليمات الشخصية والسرعة التي تناسبك جميعًا بسعر مناسب! ","تكلفة الدرس الخصوصي العادي: \u003Cbr \u002F\u003E$80\u002F1 hour \u003Cbr \u002F\u003E$912\u002F12 hours \u003Cbr \u002F\u003E$1,632\u002F24 hours \u003Cbr \u002F\u003E$2,688\u002F48 hours","إذا طلب الطالب معلماً معيناً:  \u003Cbr \u002F\u003E $92\u002F1 hour \u003Cbr \u002F\u003E $1,044\u002F12 hours \u003Cbr \u002F\u003E $1,896\u002F24 hours \u003Cbr \u002F\u003E $3,120\u002F48 hours"," * في حالة مشاركة طالبين في درس خاص يتم خصم 50٪ للطالب الثاني."]}],dir:"\u002Fprograms",path:"\u002Fprograms\u002Far",extension:".json",createdAt:"2026-10-22T16:31:30.542Z",updatedAt:"2026-04-30T16:49:24.947Z"}}],fetch:{},mutations:void 0}}("تفاصيل دورات معهد التمريض  نحن نقدم في مينتور دورات متعددة , وهي كالتالي:")));